import 'package:material_ui/material_ui.dart';

/// 阅读与富文本编辑共用的块级 AI 标识。提示文案由宿主按当前语言提供。
class AiContentBadge extends StatelessWidget {
  const AiContentBadge({super.key});

  static String Function(BuildContext)? descriptionOf;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Align(
      alignment: AlignmentDirectional.centerStart,
      child: Tooltip(
        message:
            descriptionOf?.call(context) ??
            'This content has been partially or fully generated by AI',
        child: Text(
          'AI',
          style: theme.textTheme.labelSmall?.copyWith(
            color: theme.colorScheme.onSurfaceVariant,
            fontWeight: FontWeight.bold,
          ),
        ),
      ),
    );
  }
}
